"""Canonical workflow-autonomy v1 output schemas shared by every gate.

The registry is stored as a compressed, deterministic JSON payload so the
twelve executables cannot drift through hand-maintained copies.
"""

from __future__ import annotations

import base64
import json
import zlib


_REGISTRY = ""

SCHEMAS = json.loads(zlib.decompress(base64.b64decode(_REGISTRY)))

# Completion evidence identifies the exact committed tree, not a bare object ID.
# Keep this explicit beside the generated registry so the public autonomy schema
# matches the `tree:<oid>` tokens written and verified by the gate.
SCHEMAS["autonomy"]["properties"]["repair"]["oneOf"][1]["properties"][
    "evidence"
]["items"]["properties"]["tree_token"] = {
    "type": "string",
    "pattern": r"^tree:(?:[0-9a-f]{40}|[0-9a-f]{64})$",
}
SCHEMAS["autonomy"]["properties"]["repair"]["oneOf"][1]["properties"][
    "baseline_entries"
]["items"]["properties"]["mode"] = {
    "type": "string",
    "pattern": r"^[0-7]{4}$",
}


def schema_for(gate: str) -> dict:
    return SCHEMAS[gate]
